package com.example.planyourtrip.service;
import com.example.planyourtrip.dto.ExpenseDto; import com.example.planyourtrip.exception.ApiException; import com.example.planyourtrip.model.*; import com.example.planyourtrip.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ExpenseService { private final ExpenseRepository repo; private final TripService trips; public ExpenseService(ExpenseRepository repo,TripService trips){this.repo=repo;this.trips=trips;} public List<ExpenseDto> list(Long uid,Long tripId){trips.ownerTrip(uid,tripId);return repo.findByTripOwnerIdAndTripId(uid,tripId).stream().map(this::toDto).toList();}
 @Transactional public ExpenseDto create(Long uid,Long tripId,ExpenseDto d){Trip trip=trips.ownerTrip(uid,tripId); Expense e=new Expense(); e.setTrip(trip); apply(e,d); return toDto(repo.save(e));} @Transactional public void delete(Long uid,Long id){repo.delete(repo.findByIdAndTripOwnerId(id,uid).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Expense not found")));}
 private void apply(Expense e,ExpenseDto d){e.setTitle(d.title());e.setCategory(d.category());e.setAmount(d.amount());e.setDate(d.date());} private ExpenseDto toDto(Expense e){return new ExpenseDto(e.getId(),e.getTrip().getId(),e.getTitle(),e.getCategory(),e.getAmount(),e.getDate());}}
